mapper.select:
select mn.*
from SYS_Company mn

    
        and mn.c_id = #{params.cId}
    
    
        and mn.te_id = #{params.teId}
    
    
        and mn.c_state = #{params.cState}
    
    
        and mn.c_type = #{params.cType}
    
    
        
            
                and likeCname(#{params.cName}, mn.C_Id) = true
            
            
                and mn.C_Name like concat('%',#{params.cName},'%')
            
        
    
    
        and mn.C_Code like concat('%', #{params.cCode}, '%')
    
    
        and mn.C_Creditcode like concat('%', #{params.cCreditcode}, '%')
    
    
        and mn.C_Name in
        
            #{payName}
        
    
    
        and mn.C_ContactPersonTel like concat('%', #{params.cContactpersontel}, '%')
    
    
        and mn.C_ContactPerson like concat('%', #{params.cContactperson}, '%')
    
    
        and mn.C_Type not in
        
            #{type}
        
    
    
        and mn.C_Type in
        
            #{type}
        
    
    
        and mn.C_Id in (select distinct D_Company_Id from Sys_Department where D_Type=1 and D_Company_Id is not
        null)
    
    
        and mn.C_Id in
        
            #{cId}
        
    
    
        and mn.C_Id in
        
            #{includeCId}
        
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by
        case
        
            when C_ID = #{modelCId} then #{index}
        
        ELSE 99999
        end asc,
        mn.C_CreateTime desc
    
    
        order by mn.C_CreateTime desc

select c.*, dp.pdName from SYS_Company c inner join ( select u.C_ID, max(d.PD_Name) as pdName from SYS_User u left join SYS_Position_User_P pu on u.U_ID = pu.U_ID left join SYS_Position_P p on pu.PP_ID = p.PP_ID left join SYS_Department_P d on d.PD_ID = p.PD_ID
u.C_ID is not null
and d.P_Id = #{params.pId}
and d.PD_Type = #{params.pdType}
and d.PD_Code in
#{pdCode}
group by u.C_ID ) dp on dp.C_ID = c.C_ID
c.C_ID is not null
and c.C_ID = #{params.cId}
and c.C_ID not in
#{excludeCId}
and c.C_Name like concat('%', #{params.cName}, '%')
